<?php

declare(strict_types=1);

namespace App\Api\Connections;

use App\Contracts\Domains\ApiSender;
use App\Support\CallKey;
use App\Values\ApiAccepted;

/**
 * The API of Connections, generated by php artisan journal:api; run it again instead of editing.
 */
final readonly class ConnectionApi
{
    public function __construct(private ApiSender $sender) {}

    public function cancelProjectCommand(
        string $requestKey,
    ): ApiAccepted {
        return $this->sender->send(CancelProjectCommandPayload::from([
            'requestKey' => $requestKey,
        ]));
    }

    public function readProjectCommandStatus(
        string $bindingId,
        string $requestKey,
    ): ProjectCommandStatus {
        return $this->sender->send(ReadProjectCommandStatusPayload::from([
            'bindingId' => $bindingId,
            'requestKey' => $requestKey,
        ]));
    }

    /**
     * @param  list<string>  $argv
     */
    public function runProjectCommand(
        string $bindingId,
        array $argv,
        CallKey $requestKey = new CallKey(),
        string|null $stdin = null,
    ): ProjectCommandFrames {
        return $this->sender->send(RunProjectCommandPayload::from([
            'bindingId' => $bindingId,
            'argv' => $argv,
            'requestKey' => $requestKey,
            'stdin' => $stdin,
        ]));
    }
}
